import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0058 — Logout completo da Keycloak: console web e desktop (M21, Onda C)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0058-logout-completo-da-keycloak.md","filePath":"adr/0058-logout-completo-da-keycloak.md"}'),c={name:"adr/0058-logout-completo-da-keycloak.md"};function n(d,e,s,l,r,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0058-—-logout-completo-da-keycloak-console-web-e-desktop-m21-onda-c" tabindex="-1">ADR-0058 — Logout completo da Keycloak: console web e desktop (M21, Onda C) <a class="header-anchor" href="#adr-0058-—-logout-completo-da-keycloak-console-web-e-desktop-m21-onda-c" aria-label="Permalink to &quot;ADR-0058 — Logout completo da Keycloak: console web e desktop (M21, Onda C)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-16, decisione dell&#39;owner); recepita in <code>Specifications.md</code> v1.7 (2026-11-16); implementata e rilasciata con la 1.7.2 (la causa del sintomo di E2BR resta da accertare, vedi «Conseguenze»)</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.7 (2026-11-16): §1.3 (punto «Uscita»), §3.3.1 (tabella e «Realm già importato») e Appendice C.4</td></tr><tr><td><strong>Data</strong></td><td>2026-11-15</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§1.3 (flusso di autenticazione del client desktop, <code>Specifications.md:170</code>; D-08 sul redirect, <code>:209</code>); §3.3.1 (configurazione Keycloak: client desktop e client web, <code>:1026-1037</code>); A-08 e D-05 (Keycloak gestisce solo identità e ruoli globali); ADR-0011 (modalità del redirect), ADR-0029 (il workbench web usa la sessione della pagina), ADR-0052 (rebrand: nomi dei client e URI registrati)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>no, è un&#39;integrazione.</strong> Lo spec descrive l&#39;accesso ma non l&#39;uscita: va aggiunto a §1.3 il flusso di logout del desktop (revoca, logout dal back-channel, <code>prompt=login</code> dopo un&#39;uscita esplicita) e a §3.3.1 il redirect post-logout della console (<code>/signed-out</code>). Nessuna decisione di §0 cambia</td></tr><tr><td><strong>Superfici</strong></td><td>console (prove: vitest di <code>web/src/auth/oidc.test.ts</code> e <code>guards.test.tsx</code>; e2e <code>web/e2e/app.spec.ts</code> sulla pagina <code>/signed-out</code>; il logout contro Keycloak vero è un caso manuale di <a href="./../qa/m21-correttivi.html"><code>m21-correttivi.md</code></a>) · workbench web (stessa sessione della pagina: uscire dalla console o dal workbench è lo stesso logout, e vale la stessa prova) · desktop (prove: unit Go di <code>apps/desktop/internal/auth/logout_test.go</code> con un server OIDC finto su revoca e logout dagli endpoint della discovery e su <code>prompt=login</code>; QA manuale sullo stack) · cloud (nessuna modifica ai file del realm <code>deploy/keycloak/realm-clarae.json</code> e <code>deploy/keycloak-prod/realm-clarae.json</code>; si estende <code>services/cloud/internal/keycloak/realm_test.go</code>; nessuna API, database o sync). Nessuna voce nuova del registro delle funzioni</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>L&#39;owner segnala che «Esci» non esce davvero: dopo il logout si rientra senza password. Il codice dice che l&#39;uscita dalla console c&#39;è, e dice anche perché il sintomo può comunque comparire.</p><p><strong>Console web.</strong> <code>signOut</code> chiama <code>UserManager.signoutRedirect()</code> (<code>web/src/auth/oidc.ts:188-190</code>): la libreria <code>oidc-client-ts</code> aggiunge l&#39;<code>id_token_hint</code> dell&#39;utente salvato. Il <code>UserManager</code> è creato con <code>post_logout_redirect_uri = ${origin}/</code> (<code>oidc.ts:127</code>) e senza <code>revokeTokensOnSignout</code>. Dopo il ritorno su <code>/</code>, <code>RequireAuth</code> (<code>web/src/auth/guards.tsx:13-17</code>) vede «nessun utente» e lancia subito <code>signIn</code>: se Keycloak ha ancora una sessione SSO, l&#39;accesso è immediato e <strong>il logout non si vede</strong>. Se invece Keycloak rifiuta il <code>post_logout_redirect_uri</code> (non registrato), non chiude la sessione SSO.</p><p><strong>Desktop.</strong> Il logout (<code>apps/desktop/internal/auth/auth.go:619-631</code>) chiama <code>revokeRefresh</code> (<code>oidc_native.go:280-293</code>), che manda il refresh token a un URL <strong>fisso</strong> (<code>&lt;issuer&gt;/protocol/openid-connect/revoke</code>), non controlla lo status HTTP della risposta e non chiude la sessione di Keycloak: nel browser di sistema il cookie SSO resta, e il login successivo non chiede la password.</p><p><strong>Il realm.</strong> <code>deploy/keycloak*/realm-clarae.json</code> ammette per il client web il post-logout dell&#39;origine (<code>${WEB_UI_ORIGIN}/*</code> in produzione, <code>http://localhost:5174/*##http://localhost:18081/*</code> in sviluppo). Il test <code>TestProductionRealmWebClientUsesPublicOrigin</code> (<code>realm_test.go</code>) controlla solo <code>${WEB_UI_ORIGIN}/</code>. Il client desktop ha <code>clarae://auth/logout</code> e <code>http://127.0.0.1/*</code>.</p><p><strong>Nota di diagnosi (non ancora fatta, passo 0 di M21).</strong> Keycloak parte con <code>start-dev --import-realm</code> nello stack di sviluppo (<code>deploy/docker/compose.dev.yaml:70</code>) e nelle dipendenze k3d (<code>deploy/k3d/deps.yaml:90</code>), e, secondo il piano, anche su E2BR. <code>--import-realm</code> <strong>non sovrascrive un realm già esistente</strong>: le modifiche al file JSON non hanno effetto su un realm creato prima (lo dice anche <code>deploy/compose/README.md:25</code>). Il client <code>clarae-web</code> di E2BR può quindi avere <code>post.logout.redirect.uris</code> vecchi, o un identity provider o un broker con una sessione propria. <strong>La causa precisa non è stata accertata</strong> (nessuna riproduzione sullo stack né lettura del realm di E2BR è stata fatta). Il testo originale chiedeva di riprodurla e registrarla qui prima dell&#39;accettazione; l&#39;owner ha accettato l&#39;ADR il 2026-11-16 <strong>senza</strong> questa verifica, che resta un punto aperto: stack con <code>task stack-up</code> e <code>task dev-cloud</code>, Keycloak 26 come su E2BR; poi, su E2BR, lettura del client <code>clarae-web</code> nel realm attivo. Le correzioni qui sotto valgono qualunque sia la causa.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="console-web-web" tabindex="-1">Console web (<code>web/</code>) <a class="header-anchor" href="#console-web-web" aria-label="Permalink to &quot;Console web (`web/`)&quot;">​</a></h3><ol><li><strong><code>UserManager</code> con <code>revokeTokensOnSignout: true</code>.</strong> <code>signOut</code> (<code>web/src/auth/oidc.ts</code>) legge l&#39;utente salvato e passa <strong>esplicitamente</strong> <code>id_token_hint</code> (se c&#39;è un ID token), <code>client_id</code> (come parametro aggiuntivo della richiesta) e <code>post_logout_redirect_uri = ${origin}/signed-out</code>: non ci si affida a ciò che la libreria ricorda. <strong>Come implementato</strong> (<code>web/src/auth/oidc.ts</code>): l&#39;opzione <code>revokeTokensOnSignout</code> <strong>non</strong> è impostata (<code>oidc.test.ts</code> lo verifica), perché una revoca che fallisce interromperebbe l&#39;uscita della libreria lasciando l&#39;utente connesso; <code>signOut</code> chiama <code>revokeTokens()</code> a parte, a miglior sforzo, poi <code>signoutRedirect</code>, e se il provider non risponde rimuove comunque l&#39;utente e porta a <code>/signed-out</code>.</li><li><strong>Pagina pubblica <code>/signed-out</code></strong> (<code>web/src/App.tsx</code>, <strong>fuori</strong> da <code>RequireAuth</code>): «Sei uscito da Clarae notanda» con il pulsante «Accedi». <strong>Nessun login automatico</strong>: l&#39;uscita è visibile.</li><li><strong><code>prompt=login</code> al primo accesso dopo un&#39;uscita esplicita.</strong> <code>signOut</code> scrive il marcatore <code>clarae.auth.forceLogin</code> in <code>localStorage</code> (non <code>sessionStorage</code>: deve sopravvivere alla scheda); il <code>signIn</code> successivo passa <code>prompt: &#39;login&#39;</code>, così Keycloak chiede le credenziali anche se una sessione SSO sopravvive (broker, realm vecchio). Il marcatore si cancella al login riuscito (<code>completeSignIn</code>). Se <code>localStorage</code> è bloccato il marcatore non si tiene e il prompt non è forzato. Un accesso che non segue un&#39;uscita esplicita (scadenza della sessione, primo accesso) non lo usa.</li><li><strong>Realm.</strong> I file <code>deploy/keycloak*/realm-clarae.json</code> coprono già <code>/signed-out</code> (in sviluppo con il carattere jolly, in produzione con <code>${WEB_UI_ORIGIN}/*</code>): nessuna modifica ai file. <code>services/cloud/internal/keycloak/realm_test.go</code> verifica ora che il realm di produzione ammetta <code>${WEB_UI_ORIGIN}/signed-out</code> (oltre a <code>${WEB_UI_ORIGIN}/</code>) e il nuovo <code>TestDevelopmentRealmWebClientAllowsTheSignedOutPage</code> che quello di sviluppo lo ammetta su <code>http://localhost:5174</code> e <code>http://localhost:18081</code>.</li><li><strong>Realm già esistenti.</strong> Dove il realm è stato importato prima, le modifiche si fanno <strong>dalla console di Keycloak</strong>, non dal file (vedi la nota di diagnosi): <code>post.logout.redirect.uris</code> del client <code>clarae-web</code> deve ammettere <code>&lt;origine&gt;/signed-out</code>. Lo si scrive nella guida admin (sezione di Keycloak e aggiornamento).</li></ol><h3 id="desktop-apps-desktop-internal-auth" tabindex="-1">Desktop (<code>apps/desktop/internal/auth</code>) <a class="header-anchor" href="#desktop-apps-desktop-internal-auth" aria-label="Permalink to &quot;Desktop (`apps/desktop/internal/auth`)&quot;">​</a></h3><ol start="6"><li><strong>Revoca dal <code>revocation_endpoint</code> della discovery</strong>, non dall&#39;URL fisso, con controllo dello status HTTP (uno status non 2xx si registra nel log come avviso; il logout continua). La discovery del client è già eseguita (<code>oidc.NewProvider</code>); gli endpoint che <code>provider.Endpoint()</code> non espone (<code>revocation_endpoint</code>, <code>end_session_endpoint</code>) si leggono dalle claim del documento (<code>Provider.Claims</code>, <code>discoveredMeta</code> in <code>oidc_native.go</code>) e restano in memoria nel servizio (<code>idpMeta</code>). Se il documento non annuncia <code>revocation_endpoint</code>, si ricade sull&#39;URL di Keycloak derivato dall&#39;issuer (<code>&lt;issuer&gt;/protocol/openid-connect/revoke</code>); per <code>end_session_endpoint</code> non c&#39;è ripiego. Dopo un riavvio, a sessione ripristinata e non ancora usata, il logout rifà la discovery (<code>ensureOAuth</code>).</li><li><strong>Logout back-channel su <code>end_session_endpoint</code>, prima della revoca.</strong> Un <code>POST</code> con <code>client_id</code> e <code>refresh_token</code> (senza browser, senza <code>id_token_hint</code>) chiude la sessione di Keycloak lato server (anche la sessione offline del token): è il modo che Keycloak documenta per i client pubblici senza browser, e <strong>va confermato sullo stack</strong> (caso manuale di <a href="./../qa/m21-correttivi.html"><code>m21-correttivi.md</code></a>). Va <strong>prima</strong> della revoca perché un token già revocato non identifica più la sessione a cui appartiene: l&#39;ordine è logout di sessione, poi revoca (<code>endIdentityProviderSession</code>). Non apre alcuna finestra e non richiede un <code>post_logout_redirect_uri</code>.</li><li><strong><code>prompt=login</code> al login successivo a un&#39;uscita esplicita.</strong> Il file <code>auth-logged-out</code> nella cartella dati dell&#39;app (accanto a <code>auth.json</code>, che il logout cancella; non è nel vault e non si sincronizza) sopravvive al riavvio e fa aggiungere <code>prompt=login</code> all&#39;URL di autorizzazione (<code>oauth2.SetAuthURLParam</code>); si cancella dopo un login completato. Se non si riesce a scriverlo, il logout lo registra nel log e prosegue.</li><li><strong>Controlli sugli endpoint.</strong> I due endpoint nuovi passano dallo stesso controllo degli altri (<code>checkEndpoint</code> e <code>transport.CheckSecureURL</code>: niente URL in chiaro).</li><li><strong>Ordine con ADR-0057.</strong> Il logout resta: ferma la sync (<code>PauseAll</code>), revoca il dispositivo (ADR-0057), chiude la sessione dell&#39;identity provider (punto 7) e revoca il token (punto 6), scrive il marcatore del punto 8, poi <code>clearSession</code>. I passi di rete hanno un tetto comune di 8 s. Una sessione ospitata (<code>opts.Hosted</code>, il core nel browser) non esegue nulla di tutto questo: i token sono della pagina.</li></ol><h3 id="prove" tabindex="-1">Prove <a class="header-anchor" href="#prove" aria-label="Permalink to &quot;Prove&quot;">​</a></h3><ul><li>vitest per <code>oidc.ts</code> (<code>oidc.test.ts</code>): opzioni del <code>UserManager</code>, <code>signOut</code> con <code>id_token_hint</code>, <code>client_id</code> e <code>post_logout_redirect_uri</code>, <code>prompt=login</code> dopo l&#39;uscita e non dopo una scadenza; e2e <code>web/e2e/app.spec.ts</code>: <code>/signed-out</code> senza redirect automatico.</li><li>Test Go del realm esteso (<code>go test ./internal/keycloak/...</code> nel cloud).</li><li>Unit Go del desktop con un server OIDC finto (<code>logout_test.go</code>): revoca e logout dagli endpoint della discovery e ripiego sull&#39;URL di Keycloak, status non 2xx tollerato, rete che non risponde senza bloccare l&#39;uscita, <code>prompt=login</code> solo dopo l&#39;uscita esplicita.</li><li><strong>QA manuale sullo stack e su E2BR:</strong> Esci (web e desktop) → pagina «uscito» (web) → Accedi chiede la password.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Solo <code>/signed-out</code> e <code>prompt=login</code>, senza <code>revokeTokensOnSignout</code></strong> — scartata: il refresh token resterebbe valido fino alla scadenza e un logout «finto» non lo invaliderebbe.</li><li><strong>Logout nel browser di sistema anche per il desktop</strong> (aprire <code>end_session_endpoint</code> con <code>post_logout_redirect_uri = clarae://auth/logout</code>) — scartata per ora: apre una finestra a ogni uscita, richiede l&#39;ID token (che il client non conserva) e un redirect che alcuni sistemi non recapitano. Il back-channel non ha nessuno di questi costi. Il redirect <code>clarae://auth/logout</code> resta registrato nel realm.</li><li><strong>Togliere il login automatico di <code>RequireAuth</code> per ogni rotta</strong> — scartata: cambierebbe l&#39;esperienza di chi arriva con un link a una pagina protetta. Solo l&#39;uscita esplicita ha la pagina propria.</li><li><strong>Correggere solo il realm</strong> — scartata come unica misura: non copre un realm già importato né un broker con sessione propria; il realm si controlla comunque nel passo 0.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Chi esce dalla console vede una pagina che lo dice e rientra solo con le credenziali. Lo stesso vale per il desktop, anche con una sessione SSO sopravvissuta.</li><li><strong>Un logout web diventa un&#39;uscita da tutte le schede della stessa origine</strong> che condividono la sessione di Keycloak; il browser non lo evita.</li><li><strong>Rischio:</strong> se il realm di E2BR non ammette <code>/signed-out</code>, Keycloak mostra l&#39;errore «URI di redirect non valido» invece di rimandare alla pagina. È la ragione della nota in guida admin (punto 5) e della prova manuale su E2BR.</li><li>Il back-channel del desktop dipende dal comportamento di Keycloak 26, <strong>non ancora provato su un Keycloak vero</strong> (le prove automatiche usano un server OIDC finto); con un identity provider diverso la chiamata può fallire senza effetti (il logout locale avviene comunque, e <code>prompt=login</code> copre la sessione residua).</li><li><strong>Da rivedere:</strong> se il desktop deve conservare l&#39;ID token per usare il logout nel browser; se la pagina <code>/signed-out</code> serve anche al workbench aperto in una scheda propria.</li><li><strong>Spec da aggiornare:</strong> §1.3 (uscita del desktop) e §3.3.1 (post-logout redirect del client web), nella v1.7 (<a href="./../spec-v1.7-proposta.html"><code>spec-v1.7-proposta.md</code></a>). <strong>Punto aperto:</strong> la causa del sintomo di E2BR (passo 0 della diagnosi) non è accertata; quando lo sarà, va registrata qui.</li></ul>',19)])])}const m=o(c,[["render",n]]);export{g as __pageData,m as default};
